begin;

/* ─────────────────────────────────────────────────────────────────────────
 * Seed app.taxonomy_categories from src/lib/taxonomy/data.generated.ts.
 *
 * Generated file — do not edit by hand. See
 * scripts/lib/taxonomy-seed.test.mjs, which fails if this file drifts from the
 * seed. Regenerate by mapping each category to
 * md5("kanjo-taxonomy-v1:<vendor_type_id>:<numeric id>") formatted as a uuid.
 *
 * Why a deterministic uuid: the dashboard's numeric ids are only unique per
 * vendor scope (186 and 187 each appear under two vendor types), and this table
 * keys on a uuid with no separate vendor_type_id column. Vendor scope is folded
 * into the id, and stored as vendor_type text matching VENDOR_TYPE_SEED.
 *
 * The current seed is flat, but parents and levels are derived from the tree so
 * a deeper taxonomy seeds correctly without changing this format.
 * ───────────────────────────────────────────────────────────────────────── */

on conflict (id) do update set
  parent_id = excluded.parent_id,
  vendor_type = excluded.vendor_type,
  name_ar = excluded.name_ar,
  name_en = excluded.name_en,
  level = excluded.level;

commit;
